const out = [];

/** Recopila todos los strings dentro del objeto (busca en keys/arrays) */
function collectStrings(obj, acc = []) {
  if (obj == null) return acc;
  if (typeof obj === 'string') { acc.push(obj); return acc; }
  if (Array.isArray(obj)) {
    for (const v of obj) collectStrings(v, acc);
  } else if (typeof obj === 'object') {
    for (const k of Object.keys(obj)) collectStrings(obj[k], acc);
  }
  return acc;
}

/** Extrae una subcadena JSON balanceada (soporta { ... } y [ ... ]).
 *  Devuelve null si no encuentra cierre balanceado. */
function extractBalanced(s) {
  const start = s.search(/[{[]/);
  if (start === -1) return null;
  const open = s[start];
  const close = open === '{' ? '}' : ']';
  let depth = 0;
  let inString = false;
  let prev = '';
  for (let i = start; i < s.length; i++) {
    const ch = s[i];
    if (ch === '"' && prev !== '\\') inString = !inString;
    if (!inString) {
      if (ch === open) depth++;
      else if (ch === close) {
        depth--;
        if (depth === 0) return s.slice(start, i + 1);
      }
    }
    prev = ch;
  }
  // Si aquí no está balanceado, intenta devolver hasta la última llave/corchete
  const lastClose = s.lastIndexOf(close);
  if (lastClose > start) return s.slice(start, lastClose + 1);
  return null;
}

/** Intento de parse seguro */
function tryJSONParse(s) {
  try { return JSON.parse(s); } catch (e) { return null; }
}

// ---- comienzo ----
const item = items[0] ? items[0].json : {};
const candidates = collectStrings(item);

// Si no hay strings, usa la representación JSON del objeto
const rawCandidate = (candidates.length ? candidates : [JSON.stringify(item)]).sort((a,b) => {
  // Prioriza candidatos que contengan "temas" y llaves
  const score = s => (s.includes('"temas"') ? 10 : 0) + (s.includes('{') ? 1 : 0);
  return score(b) - score(a);
})[0];

let parsed = null;

// 1) intenta extraer bloque balanceado y parsear
const balanced = extractBalanced(rawCandidate);
if (balanced) parsed = tryJSONParse(balanced);

// 2) si falla, intenta "unescape" de \n y \"
if (!parsed) {
  const unesc = rawCandidate.replace(/\\n/g, '\n').replace(/\\"/g, '"');
  const balanced2 = extractBalanced(unesc) || unesc;
  parsed = tryJSONParse(balanced2);
}

// 3) si aún falla, busca la clave "temas" y recorta desde la llave previa
if (!parsed) {
  const keyIdx = rawCandidate.search(/"temas"\s*:/);
  if (keyIdx !== -1) {
    const braceIdx = rawCandidate.lastIndexOf('{', keyIdx);
    if (braceIdx !== -1) {
      const substr = rawCandidate.slice(braceIdx);
      const balanced3 = extractBalanced(substr) || substr;
      parsed = tryJSONParse(balanced3);
    }
  }
}

// 4) salida: si parseó, devuelve el objeto; si no, devuelve raw para debug
if (!parsed) {
  out.push({
    json: {
      success: false,
      error: 'No se pudo parsear JSON. Revisa el campo raw para depuración.',
      raw: rawCandidate
    }
  });
  return out;
}

// Si parseó correctamente, devolvemos el objeto (ej: { temas: [...] })
out.push({ json: parsed });
return out[0].json.temas.map(t => ({ json: t }));

const out = [];

for (const item of items) {
  const temaId = item.json.sec_id;
  const subtemas = item.json.subtemas || [];

  subtemas.forEach((st, idx) => {
    out.push({
      json: {
        idTema: temaId,
        nombre: st.nombre,
        contenido: st.contenido || "", // array de párrafos
        orden: idx + 1,
        titulo: st.titulo || st.nombre
      }
    });
  });
}

return out;

const out = [];

for (const item of items) {
  const subId = item.json.sub_id;
  const nombre = item.json.nombre || "";
  const parrafos = Array.isArray(item.json.contenido) ? item.json.contenido : [item.json.contenido];

  // Determinar plantilla
  let plantilla = 2; // valor por defecto
  if (nombre.toLowerCase() === "portada") {
    plantilla = 8;
  } else if (nombre.toLowerCase() === "trivia") {
    plantilla = 10;
  }

  parrafos.forEach((texto, idx) => {
    out.push({
      json: {
        sld_activo: true,
        sld_id_subseccion: subId,
        sld_nombre: nombre,
        sld_orden: idx + 1,
        sld_plantilla: plantilla,
        sld_texto1: texto ? `<p>${texto}</p>` : "", // si no hay texto, vacío
        sld_titulo: item.json.titulo || nombre
      }
    });
  });
}

return out;

let recursoId = null;

// Buscar el recurso (el item que contiene campos rec_)
for (const it of items) {
  const j = it.json || {};
  const hasRec = Object.keys(j).some(k => k.startsWith("rec_"));
  if (hasRec && j.id !== undefined) {
    recursoId = j.id;
    break; // asumimos que solo hay uno
  }
}

// Filtramos los items que no son recurso y que no tengan "prompt"
const filtered = items.filter(it => {
  const j = it.json || {};
  const hasRec = Object.keys(j).some(k => k.startsWith("rec_"));
  const hasPrompt = "prompt" in j;
  return !hasRec && !hasPrompt;
});

// Agrupamos por sld_nombre
const grouped = {};
for (const it of filtered) {
  const j = { ...it.json };

  if (!j.sld_nombre) continue;

  if (!grouped[j.sld_nombre]) {
    grouped[j.sld_nombre] = { ...j, sld_texto1: j.sld_texto1 || "" };
  } else {
    grouped[j.sld_nombre].sld_texto1 += (grouped[j.sld_nombre].sld_texto1 ? "\n\n" : "") + (j.sld_texto1 || "");
    // mantener el menor orden para representar el primero
    if (j.sld_orden < grouped[j.sld_nombre].sld_orden) {
      grouped[j.sld_nombre].sld_orden = j.sld_orden;
    }
  }
}

// Convertimos a array y añadimos sld_fondo si es portada
const out = Object.values(grouped).map(j => {
  if (j.sld_nombre && j.sld_nombre.toLowerCase() === "portada" && recursoId) {
    j.sld_fondo = recursoId;
  }
  return { json: j };
});

return out;

const items = $items();
const datos = items.map(i => i.json);

const prompt = `
Genera una trivia de 10 preguntas en formato JSON usando la siguiente información de subtemas y contenidos:

${JSON.stringify(datos, null, 2)}

Reglas IMPORTANTES:
- Cada pregunta debe tener exactamente 4 opciones de respuesta.
- Solo UNA de las opciones puede ser válida (correcta = true).
- Aunque el texto contenga varias posibles respuestas correctas, debes escoger **únicamente una** como la válida.
- Las demás opciones deben ser distractores: incorrectas pero **coherentes** y **plausibles** dentro del tema.
- Los distractores NO deben ser también correctos según el texto original.
- Si el tema es especializado (ej. medicina), los distractores pueden basarse en términos médicos reales o relacionados, pero no deben coincidir con la respuesta válida.

El formato de salida debe ser estrictamente un JSON como este:

[
  {
    "pregunta": "texto de la pregunta",
    "respuestas": [
      { "texto": "opción 1", "correcta": false },
      { "texto": "opción 2", "correcta": true },
      { "texto": "opción 3", "correcta": false },
      { "texto": "opción 4", "correcta": false }
    ]
  }
]
`;

return [{
  chatInput: prompt
}];

// Tomamos todos los items que vienen al nodo
const items = $items();

// Buscamos el que trae output y el que trae tri_id
const outputItem = items.find(i => i.json.output);
const idItem = items.find(i => i.json.tri_id);

// Limpiamos el JSON dentro del output
let clean = outputItem.json.output
  .replace(/```json\n?/g, '')
  .replace(/```/g, '');

// Parseamos
let trivia;
try {
  trivia = JSON.parse(clean);
} catch (err) {
  throw new Error('Error parseando la trivia: ' + err.message + '\nTexto:\n' + clean);
}

// Devolvemos un solo objeto que combine ambas cosas
return [{
  json: {
    tri_id: idItem.json.tri_id,
    trivia: trivia
  }
}];

const tri_id = $json.tri_id;
const trivia = $json.trivia;

const items = trivia.map(q => {
  return {
    json: {
      tri_id: tri_id,
      pregunta: `<p>${q.pregunta}</p>`,
      respuestas: q.respuestas
    }
  };
});

return items;

const items = $items(); // todos los items que entran al nodo
const data = items.map(i => i.json); // extraemos el JSON de cada item
const result = [];

(data || []).forEach(p => {
  (p.respuestas || []).forEach(r => {
    result.push({
      json: {
        trr_id_pregunta: p.trp_id,          // ID de la pregunta
        trr_respuesta: `<p>${r.texto}</p>`, // respuesta envuelta en <p>
        correcta: r.correcta
      }
    });
  });
});

return result;

// Function node en n8n
// Filtra solo los items cuya propiedad correcta === true

return items.filter(item => item.json.correcta === true);

const lastItem = items[items.length - 1]; // el último objeto
const sldId = lastItem.json?.sld_id;      // accedemos a la propiedad

return [
  {
    json: {
      sld_id: sldId,
    }
  }
];

